package com.andrexthedev.autovybz.measurement.mic

import android.content.Context
import android.os.Build
import org.json.JSONArray
import org.json.JSONObject

/**
 * Loads `assets/autovybz/mic_profiles.json` (generated by
 * tools/micdb/generate_mic_profiles.py) and resolves the profile for the
 * running device via [Build.MANUFACTURER] / [Build.MODEL].
 */
class MicProfileDatabase private constructor(
    val profiles: List<MicProfile>,
    val default: MicProfile,
    val notice: String,
) {

    fun forDevice(manufacturer: String = Build.MANUFACTURER ?: "", model: String = Build.MODEL ?: ""): MicProfile =
        MicProfileMatcher.match(profiles, default, manufacturer, model)

    fun byId(id: String): MicProfile? = if (id == default.id) default else profiles.firstOrNull { it.id == id }

    companion object {
        const val ASSET_PATH = "autovybz/mic_profiles.json"

        @Volatile private var cached: MicProfileDatabase? = null

        fun get(context: Context): MicProfileDatabase =
            cached ?: synchronized(this) {
                cached ?: context.applicationContext.assets.open(ASSET_PATH).bufferedReader().use {
                    parse(it.readText())
                }.also { cached = it }
            }

        /** Pure parse (unit-tested on the JVM with org.json as testImplementation). */
        fun parse(json: String): MicProfileDatabase {
            val root = JSONObject(json)
            val archetypes = root.getJSONObject("archetypes")
            val archetypeCurves = HashMap<String, Map<InputSource, ResponseCurve>>()
            val archetypeLabels = HashMap<String, String>()
            for (key in archetypes.keys()) {
                val a = archetypes.getJSONObject(key)
                archetypeCurves[key] = parseCurves(a.getJSONObject("curves"))
                archetypeLabels[key] = a.optString("label", key)
            }
            val defaultId = root.getString("default")
            val default = MicProfile(
                id = defaultId,
                label = archetypeLabels[defaultId] ?: defaultId,
                manufacturer = null,
                modelPatterns = emptyList(),
                confidence = ProfileConfidence.ESTIMATED,
                curves = archetypeCurves[defaultId] ?: error("default archetype '$defaultId' missing"),
            )
            val devices = root.optJSONArray("devices") ?: JSONArray()
            val profiles = ArrayList<MicProfile>(devices.length())
            for (i in 0 until devices.length()) {
                val d = devices.getJSONObject(i)
                val curves = when {
                    d.has("curves") -> parseCurves(d.getJSONObject("curves"))
                    d.has("curveRef") -> archetypeCurves[d.getString("curveRef")]
                        ?: error("unknown curveRef ${d.getString("curveRef")}")
                    else -> default.curves
                }
                val models = d.optJSONArray("models") ?: JSONArray()
                profiles += MicProfile(
                    id = d.getString("id"),
                    label = d.optString("label", d.getString("id")),
                    manufacturer = d.getString("manufacturer"),
                    modelPatterns = (0 until models.length()).map { Regex(models.getString(it), RegexOption.IGNORE_CASE) },
                    confidence = when (d.optString("confidence", "estimated").lowercase()) {
                        "measured" -> ProfileConfidence.MEASURED
                        "community" -> ProfileConfidence.COMMUNITY
                        else -> ProfileConfidence.ESTIMATED
                    },
                    curves = curves,
                    notes = d.optString("notes").ifEmpty { null },
                )
            }
            return MicProfileDatabase(profiles, default, root.optString("notice"))
        }

        private fun parseCurves(o: JSONObject): Map<InputSource, ResponseCurve> {
            val out = LinkedHashMap<InputSource, ResponseCurve>()
            for (key in o.keys()) {
                val source = runCatching { InputSource.valueOf(key) }.getOrNull() ?: continue
                val arr = o.getJSONArray(key)
                out[source] = ResponseCurve((0 until arr.length()).map {
                    val p = arr.getJSONArray(it); p.getDouble(0) to p.getDouble(1)
                })
            }
            return out
        }
    }
}
